codeExercise.solution:
function breakingChanges(oldSchema, newSchema) {
  const reasons = [];
  for (const name of Object.keys(oldSchema)) {
    const before = oldSchema[name];
    const after = newSchema[name];
    if (!after) { reasons.push(`removed:${name}`); continue; }
    if (after.type !== before.type) reasons.push(`type:${name}`);
    if (after.nullable && !before.nullable) reasons.push(`nullable:${name}`);
  }
  return reasons.sort();
}

