codeExercise.testSource:
describe("serializeTapList", () => {
  let rows;
  beforeEach(() => {
    rows = [
      { id: 42, rider_id: 7, fare_cents: 275, internal_cost_cents: 190,
        settlement_batch_id: 4471, void_reason: null },
      { id: 43, rider_id: 7, fare_cents: 0, internal_cost_cents: 0,
        settlement_batch_id: 4471, void_reason: "duplicate_tap" }
    ];
  });

  it("never emits internal or storage-only columns", () => {
    const out = serializeTapList(rows);
    for (const r of out) {
      expect(Object.prototype.hasOwnProperty.call(r, "internal_cost_cents")).toBe(false);
      expect(Object.prototype.hasOwnProperty.call(r, "settlement_batch_id")).toBe(false);
      expect(Object.prototype.hasOwnProperty.call(r, "fare_cents")).toBe(false);
    }
  });

  it("always emits voidReason, null when absent", () => {
    const out = serializeTapList(rows);
    expect(Object.prototype.hasOwnProperty.call(out[0], "voidReason")).toBe(true);
    expect(out[0].voidReason).toBe(null);
    expect(out[1].voidReason).toBe("duplicate_tap");
  });

  it("does not mutate its input rows", () => {
    const before = JSON.stringify(rows);
    serializeTapList(rows);
    expect(JSON.stringify(rows)).toBe(before);
  });

  it("serializes a zero fare correctly", () => {
    const out = serializeTapList(rows);
    expect(out[1].fare).toEqual({ amount: 0, currency: "USD" });
  });
});

