describe("nextCursor", () => {
  it("returns a cursor built from the last row of a full page", () => {
    expect(nextCursor([["2026-09-04", 4], ["2026-09-03", 3]], 2)).toBe("2026-09-03|3");
  });

  it("returns null on a short final page", () => {
    expect(nextCursor([["2026-09-01", 1]], 2)).toBe(null);
  });

  it("returns null for an empty result set", () => {
    expect(nextCursor([], 2)).toBe(null);
  });

  it("includes the id tiebreaker when timestamps collide", () => {
    expect(nextCursor([["2026-09-05", 9], ["2026-09-05", 7]], 2)).toBe("2026-09-05|7");
  });

  it("uses the last row, not the first", () => {
    expect(nextCursor([["2026-09-09", 90], ["2026-09-08", 80], ["2026-09-07", 70]], 3))
      .toBe("2026-09-07|70");
  });
});
